// OWNER: N7
// Tap replaces hover (IOS-SPEC §4.1 rule 5, §4.5, §4.7): every bin, gap, wash, cap, mark and seam answers a tap with
// its generated sentence, made from the same numbers as the drawing — the reference's tooltip lines (display.mjs,
// byte-equal, generated by `DisplayBuild.tip`) joined into one line for the peek row. Every count names its
// denominator ("0 occurrences in 6.2k tokens — looked, found none"); a low bin never prints a rate; ¹ and ≈ are spelled
// out here when the bar was too narrow to carry them. What a tap then does follows `viewport.mjs` `open()`:
//   · a mark → select its occurrence (or passage): the inspector opens Then;
//   · an observed bin or a low-coverage tick → select the bin: its drawer opens (N8), the sentence goes to the peek row;
//   · a wash → its sentence, and the list of its records (`openShelf` "washes");
//   · an empty bin, a gap, a cap, coverage, the seam → only its sentence.

import CoreGraphics
import ScrollsContracts
import ScrollsCore
import ScrollsScrollModel
import UIKit

/// The sentence of a tapped primitive.
enum TapSentences {
  /// The words of a primitive: its tooltip lines joined with " · ", plus the strand summary under an observed bin.
  static func sentence(_ build: DisplayBuild, _ part: DisplayBuild.Part, _ id: PrimID) -> String? {
    guard var lines = build.tip(part, id), !lines.isEmpty else { return nil }
    if part == .lanes, case .bin(let ref)? = build.list(part).refs[id] {
      if let lane = build.model.lanes.first(where: { $0.key == ref.lane.rawValue }),
        let strand = lane.strands.first(where: { $0.ref == ref.strand }), Int(ref.index) < strand.cols.count,
        strand.cols.state[Int(ref.index)] == .observed {
        lines.append(ScrollWords.strandSummary(lane: lane, strand: strand, tier: build.model.tier))
      }
    }
    return lines.joined(separator: " · ")
  }

  /// What a hit should do.
  enum Action: Equatable {
    case select(ViewState.Selection)
    case selectBin(String)
    case wash(lane: String, strand: String, title: String)
    case sentenceOnly
  }

  static func action(_ build: DisplayBuild, _ part: DisplayBuild.Part, _ entry: HitEntry) -> Action {
    guard let ref = build.list(part).refs[entry.id] else { return .sentenceOnly }
    switch ref {
    case .occurrence(let o): return .select(ViewState.Selection(type: "occurrence", id: .number(Int(o.rawValue))))
    case .passage(let p): return .select(ViewState.Selection(type: "passage", id: .number(Int(p.rawValue))))
    case .relationship(let r): return .select(ViewState.Selection(type: "relationship", id: .number(Int(r.rawValue))))
    case .bin(let b):
      // Only an observed bar and a low-coverage tick open the drawer; an absent bin and a cap answer in words.
      guard entry.hitClass == .bin, entry.openable else { return .sentenceOnly }
      let lane = build.model.lanes.first { $0.key == b.lane.rawValue }
      let st = lane?.strands.first { $0.ref == b.strand }
      let state = st.flatMap { Int(b.index) < $0.cols.count ? $0.cols.state[Int(b.index)] : nil }
      guard state == .observed || state == .low else { return .sentenceOnly }
      return .selectBin(ScrollModel.selectionID(b))
    case .wash(let w): return .wash(lane: w.lane.rawValue, strand: w.strand, title: "Records dated \(w.label)")
    case .shelf, .seam, .band, .none: return .sentenceOnly
    }
  }
}

extension ScrollModel {
  /// A tap at a canvas point: the topmost hit answers (priority mark > arc > cap > bin > wash > band; 12 pt tolerance for
  /// marks, caps and arcs). Two or more marks within 6 pt of each other open the ambiguity chooser.
  func tap(at p: CGPoint) {
    guard let build else { return }
    let part: DisplayBuild.Part = Double(p.y) < stripHeight ? .top : .lanes
    if part == .lanes, Double(p.y) > Double(canvasSize.height) - occludedBottom { return }
    let list = build.list(part)
    let hits = list.hit.hits(contentPoint(p, list: list, part: part), tolerance: CGFloat(HitGrid.touchTolerance), vantage: vantage)
    guard let best = hits.first else {
      app.experience.bridge.peekSentence = nil
      return
    }
    // Ambiguity: marks whose centres lie within 6 pt of each other.
    let marks = hits.filter { $0.entry.hitClass == .mark }
    if marks.count >= 2 {
      let c0 = marks[0].entry.bounds
      let close = marks.filter { abs($0.entry.bounds.midX - c0.midX) <= 6 * contentScale && abs($0.entry.bounds.midY - c0.midY) <= 6 }
      if close.count >= 2 {
        openChooser(close.prefix(6).map(\.entry), at: p)
        return
      }
    }
    perform(best.entry, part: part, build: build)
  }

  /// Content points per canvas point along x right now (the hit grid is in content points at the build's zoom).
  var contentScale: Double {
    guard let build else { return 1 }
    return build.lanes.hit.pointsPerDay * axis.daysPerPoint
  }

  /// A canvas point in the content coordinates of a list's hit grid.
  func contentPoint(_ p: CGPoint, list: DisplayList, part: DisplayBuild.Part) -> CGPoint {
    let day = frame.day(x: Double(p.x))
    let x = (day - Double(list.originDay)) * list.hit.pointsPerDay
    let y = part == .top ? Double(p.y) : Double(p.y) - stripHeight + scrollY
    return CGPoint(x: x, y: y)
  }

  /// Does what a hit asks for.
  func perform(_ entry: HitEntry, part: DisplayBuild.Part, build: DisplayBuild) {
    let sentence = TapSentences.sentence(build, part, entry.id)
    switch TapSentences.action(build, part, entry) {
    case .select(let sel):
      app.experience.bridge.peekSentence = nil
      app.experience.select(sel)
    case .selectBin(let id):
      app.experience.bridge.peekSentence = sentence
      app.experience.select(ViewState.Selection(type: "bin", id: .string(id)))
    case .wash(let lane, let strand, let title):
      app.experience.bridge.peekSentence = sentence
      app.experience.openShelf(ShelfRef(which: "washes", lane: lane, strand: strand, title: title))
    case .sentenceOnly:
      app.experience.bridge.peekSentence = sentence
      if let sentence, UIAccessibility.isVoiceOverRunning { AccessibilityNotification.Announcement(sentence).post() }
    }
    requestFrame()
  }

  private func openChooser(_ entries: [HitEntry], at p: CGPoint) {
    guard let build else { return }
    var rows: [AmbiguityChoice.Row] = []
    for e in entries {
      guard let ref = build.lanes.refs[e.id], case .mark(let l, let s, let mi) = build.laneMeta[Int(e.id.rawValue)].source,
        let mk = build.model.lanes[l].strands[s].marks?[mi] else { continue }
      rows.append(AmbiguityChoice.Row(id: e.id, ref: ref, date: ScrollModelBuilder.markLabel(mk), lane: build.model.lanes[l].label,
                                      kind: mk.kind, doc: mk.doc, synthetic: mk.synthetic))
    }
    guard rows.count >= 2 else {
      if let first = entries.first { perform(first, part: .lanes, build: build) }
      return
    }
    chooser = AmbiguityChoice(anchor: p, rows: rows)
  }

  /// A row of the chooser was picked.
  func choose(_ row: AmbiguityChoice.Row) {
    chooser = nil
    guard let build, let i = build.lanes.hit.entries.firstIndex(where: { $0.id == row.id }) else { return }
    perform(build.lanes.hit.entries[i], part: .lanes, build: build)
  }
}
